// Structure for dynamic memory allocation
typedef struct dynamic_array {
    int *array;
    int size;
    int capacity;
} dynamic_array;

// Function to initialize the dynamic array
dynamic_array* array_init(int capacity) {
    dynamic_array* arr = (dynamic_array*)malloc(sizeof(dynamic_array));
    arr->array = (int*)malloc(sizeof(int) * capacity);
    arr->size = 0;
    arr->capacity = capacity;
    return arr;
}

// Function to insert an element into the dynamic array
void array_insert(dynamic_array* arr, int element) {
    if (arr->size == arr->capacity) {
        arr->capacity *= 2;
        arr->array = (int*)realloc(arr->array, sizeof(int) * arr->capacity);
    }
    arr->array[arr->size++] = element;
}

// Function to print the dynamic array
void print_array(dynamic_array* arr) {
    for (int i = 0; i < arr->size; i++) {
        printf("%d ", arr->array[i]);
    }
    printf("\n");
}

// Equivalent function of Java's FastScanner
typedef struct fast_scanner {
    FILE* file;
    char line[1000];
} fast_scanner;

fast_scanner* fps_init() {
    fast_scanner* fs = (fast_scanner*)malloc(sizeof(fast_scanner));
    fs->file = fopen("input.txt", "r");
    if (fs->file == NULL) {
        fs->file = stdin;
    }
    return fs;
}

char* next_token(fast_scanner* fs) {
    if (fs->line[0] == '\0') {
        fscanf(fs->file, "%s", fs->line);
    }
    char* token = fs->line;
    while (*token != '\0' && isspace(*token)) {
        token++;
    }
    return token;
}

int next_int(fast_scanner* fs) {
    char* token = next_token(fs);
    return atoi(token);
}

long next_long(fast_scanner* fs) {
    char* token = next_token(fs);
    return atoll(token);
}

char* next_str(fast_scanner* fs) {
    char* token = next_token(fs);
    return token;
}

// Equivalent function of Java's PrintWriter
typedef struct print_writer {
    FILE* file;
} print_writer;

print_writer* pwInit(FILE* file) {
    print_writer* pw = (print_writer*)malloc(sizeof(print_writer));
    pw->file = file;
    return pw;
}

void solution(int all, int testcase, fast_scanner* fs, print_writer* pw) {
    int n = next_int(fs);
    mod = next_int(fs);

    long dp[MAXN][MAXN];
    for (int i = 0; i < MAXN; i++) {
        for (int j = 0; j < MAXN; j++) {
            dp[i][j] = 0;
        }
    }
    dp[0][0] = 1;
    for (int i = 1; i < n; i++) {
        for (int j = 0; j < MAXN; j++) {
            for (int cnt = 0; cnt <= i; cnt++) {
                if (j - cnt >= 0) {
                    dp[i][j] += dp[i - 1][j - cnt];
                    dp[i][j] %= mod;
                    if (dp[i][j] == 0) {
                        dp[i][j] += mod;
                    }
                }
            }
        }
    }

    long sums[MAXN][MAXN];
    for (int i = 0; i < MAXN; i++) {
        for (int j = 0; j < MAXN; j++) {
            sums[i][j] = 0;
        }
    }
    for (int i = 0; i < MAXN; i++) {
        int sum = 0;
        for (int j = 0; j < MAXN; j++) {
            sum += dp[i][j];
            sum %= mod;
            if (sum == 0) {
                sum += mod;
            }
            sums[i][j] = sum;
        }
    }

    // Initialize ncr and factorial array
    factorials[0] = factorials[1] = 1;
    for (int i = 2; i < MAXN; i++) {
        factorials[i] = (factorials[i - 1] * i) % mod;
    }
    for (int i = 0; i < MAXN; i++) {
        ncr[i][0] = 1;
    }
    for (int i = 1; i < MAXN; i++) {
        for (int j = 1; j < MAXN; j++) {
            ncr[i][j] = (ncr[i - 1][j] + ncr[i - 1][j - 1]) % mod;
            if (ncr[i][j] == 0) {
                ncr[i][j] += mod;
            }
        }
    }

    long res = 0;
    for (int i = n - 2; i >= 0; i--) {
        int cnt = n - i;
        int pre = n - cnt;
        long com = (ncr[n][pre] * factorials[pre]) % mod;
        if (com == 0) {
            com += mod;
        }
        long sum = 0;
        for (int dif = 1; dif < cnt; dif++) {
            for (int inv = dif++; inv < MAXN; inv++) {
                if (dp[cnt - 2][inv] == 0) {
                    break;
                }
                if (inv - dif - 1 < 0) continue;
                long x = dp[cnt - 2][inv];
                long y = sums[cnt - 2][inv - dif - 1];
                x = (x * y) % mod;
                if (x == 0) x += mod;
                sum = (sum + x * (cnt - dif)) % mod;
            }
        }
        res = (res + sum * com) % mod;
        if (res == 0) res += mod;
    }

    fprintf(pw->file, "%ld\n", res % mod);
}

int main() {
    fast_scanner* fs = fps_init();
    FILE* stdout = stdout;
    print_writer* pw = pwInit(stdout);
    int T = 1;
    for (int t = 0; t < T; t++) {
        solution(T, t, fs, pw);
    }
